import ast, glob, re
pub = set(re.findall(r'\|\s([a-z0-9-]+)\s\|\s\d{3}\s\|', open('docs/decomposition.md').read().replace(chr(96), '')))
suf, decl = set(), 0
for f in sorted(glob.glob('harness/*/interface.py')):
    for n in ast.walk(ast.parse(open(f).read())):
        t = n.targets[0] if isinstance(n, ast.Assign) and n.targets else getattr(n, 'target', None)
        if isinstance(t, ast.Name) and t.id in ('REGISTRY', 'PROBLEM_REGISTRY') and isinstance(n.value, ast.Dict):
            suf.update(k.value for k in n.value.keys if isinstance(k, ast.Constant))
            if any(isinstance(v, ast.Tuple) and len(v.elts) >= 4 for v in n.value.values):
                decl += 1
print('published_registry_rows=%d live_harness_suffixes=%d suffixes_with_no_published_row=%d registries_declaring_extension_members=%d' % (len(pub), len(suf), len(suf - pub), decl))
"

python3 -c "
import ast, os
core = {'type','title','status','detail','retryable'}
hits = []
for dp, dn, fn in os.walk('.'):
    dn[:] = [d for d in dn if d not in ('.git', 'out', '__pycache__', 'harness')]
    for n in fn:
        if not n.endswith('.py'): continue
        p = os.path.join(dp, n)
        try: tree = ast.parse(open(p, encoding='utf-8').read())
        except Exception: continue
        for node in ast.walk(tree):
            if isinstance(node, ast.Dict) and core <= {k.value for k in node.keys if isinstance(k, ast.Constant) and isinstance(k.value, str)}:
                hits.append('%s:%d' % (os.path.relpath(p, '.'), node.lineno))
print('hand_built_problem_bodies_outside_harness=%d at=%s' % (len(hits), hits))
"

